class PrintEpoch(keras.callbacks.Callback):
    def on_epoch_begin(self, epoch, logs=None):
        print(f"Starting epoch {epoch}")
    def on_epoch_end(self, epoch, logs=None):
        print(f"Epoch {epoch} done, loss={logs['loss']:.4f}")
